import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import com.google.gson.GsonBuilder;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import org.objectweb.asm.util.*;
public final class ManorEffectiveLifecycleAuditV1 {
    private static ClassNode read(ZipFile jar,String name)throws Exception{ClassNode node=new ClassNode();new ClassReader(jar.getInputStream(jar.getEntry(name+".class")).readAllBytes()).accept(node,0);return node;}
    private static String instructions(MethodNode method){Textifier text=new Textifier();method.accept(new TraceMethodVisitor(text));return text.getText().toString();}
    public static void main(String[] arguments)throws Exception{Path out=Path.of(arguments[2]);Map<String,Object> report=new LinkedHashMap<>();try(ZipFile current=new ZipFile(arguments[0]);ZipFile original=new ZipFile(arguments[1])){for(String type:List.of("entity/EasterBossEntity","boss/ai/ManorFiveSkills")){String owner="net/farmingtales/ftboss/"+type;ClassNode node=read(current,owner),forge=read(original,owner);new net.farmingtales.ftboss.boss.ai.NativeManorMixinPlugin().postApply(owner.replace('/','.'),node,"net.farmingtales.ftboss.mixin.NativeManorRaidMixin",null);ClassWriter writer=new ClassWriter(ClassWriter.COMPUTE_MAXS);node.accept(writer);byte[] payload=writer.toByteArray();ClassNode verified=new ClassNode();new ClassReader(payload).accept(verified,0);int count=0;for(MethodNode method:verified.methods)if((method.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0){new Analyzer<>(new BasicVerifier()).analyze(owner,method);count++;}Files.write(out.resolve(type.substring(type.lastIndexOf('/')+1)+"-effective.class"),payload);Map<String,Object> entry=new LinkedHashMap<>();entry.put("methods",node.methods.stream().map(method->method.name+method.desc).toList());entry.put("interfaces",node.interfaces);entry.put("asmVerifiedMethods",count);List<String> missing=forge.methods.stream().filter(method->node.methods.stream().noneMatch(actual->actual.name.equals(method.name)&&actual.desc.equals(method.desc))).map(method->method.name+method.desc).toList();entry.put("originalSignaturesAbsentFromEffective",missing);report.put(type,entry);for(String name:List.of("onManorFiveCastStart","canShadowStrike","spawnShadowPhantom","ftboss$nativeXuanlanCue","beginManorFiveCast","finishManorFiveCast","cancelManorFiveCast","tryStart","strike","center","hitShape","echoCast")){for(String label:List.of("original","effective")){ClassNode authority=label.equals("original")?forge:node;for(MethodNode method:authority.methods)if(method.name.equals(name))Files.writeString(out.resolve(type.substring(type.lastIndexOf('/')+1)+"-"+label+"-"+name.replace('$','_')+".txt"),instructions(method));}}}report.put("scope","Exact current actual Boss/Skills NativeManorRaidMixin postApply ClassNode pipeline,not AnimationEmitter Boss branch;not native instance authority. Native baseline required.");Files.writeString(out.resolve("effective-members.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));System.out.println("failures=0;effectiveBossAndControllerVerified=true;actualRaidTargetPipelineOnly=true;productChanged=false");}}
}
